const menu=document.querySelector('.menu'),nav=document.querySelector('#nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Open navigation':'Close navigation');nav.classList.toggle('open',!open)});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
document.querySelector('#quoteForm').addEventListener('submit',async e=>{e.preventDefault();const fields=[...e.target.querySelectorAll('input:not([type="checkbox"]),select,textarea')].map(el=>`${el.closest('label')?.childNodes[0]?.textContent?.trim()||'Detail'}: ${el.value||'Not supplied'}`);const products=[...e.target.querySelectorAll('input[type="checkbox"]:checked')].map(el=>el.value);const text=['SKYWAY LUBRICANTS ENQUIRY',...fields,`Products: ${products.join(', ')||'Not selected'}`].join('\n');try{await navigator.clipboard.writeText(text)}catch{}const note=document.querySelector('#formNote');note.innerHTML='Your enquiry is ready. <a href="sms:+27615146353?body='+encodeURIComponent(text)+'">Continue in Messages</a> or call <a href="tel:+27615146353">+27 61 514 6353</a>.';e.target.querySelector('button').textContent='Enquiry prepared';});
document.querySelectorAll('.footer-policies a[href^="#"],a[href="#privacy"],a[href="#terms"]').forEach(a=>a.addEventListener('click',()=>{const panel=document.querySelector(a.getAttribute('href'));if(panel?.tagName==='DETAILS')panel.open=true}));
document.querySelector('#year').textContent=new Date().getFullYear();
